%% stem_07_scell_utilisation.m - Salt-iron cell: utilisation vs areal capacity
% Generated by tools/matlab/make_stem.py from sim/s14_scell_model/out/s14_results.json. Values: [SIMULATED] 0-D model.
% Runs in MATLAB R2019b+ and GNU Octave 8+. Output: out/stem_07_scell_utilisation.png
if exist('OCTAVE_VERSION', 'builtin'), graphics_toolkit('gnuplot'); end   % Octave only; MATLAB skips this line
fig = figure('Visible', 'off', 'Color', 'w', 'Position', [100 100 960 520]);
set(fig, 'PaperPositionMode', 'auto');
hold on; grid on; box off;
try, set(gca, 'GridColor', [0.80 0.80 0.80], 'GridAlpha', 0.6); catch, end
q = [30 60 100]; u = 100 * [1 1 1];
h0 = stem(q + -4.5, u, 'filled', 'LineWidth', 2.8, 'Color', [0.165 0.471 0.839], 'MarkerFaceColor', [0.165 0.471 0.839]);
q = [30 60 100]; u = 100 * [1 1 1];
h1 = stem(q + -1.5, u, 'filled', 'LineWidth', 2.8, 'Color', [0.922 0.408 0.204], 'MarkerFaceColor', [0.922 0.408 0.204]);
q = [30 60 100]; u = 100 * [1 1 1];
h2 = stem(q + 1.5, u, 'filled', 'LineWidth', 2.8, 'Color', [0.106 0.686 0.478], 'MarkerFaceColor', [0.106 0.686 0.478]);
q = [30 60 100]; u = 100 * [1 1 1];
h3 = stem(q + 4.5, u, 'filled', 'LineWidth', 2.8, 'Color', [0.929 0.631 0.000], 'MarkerFaceColor', [0.929 0.631 0.000]);
plot([20 110], [80 80], 'k--'); xlim([20 110]); ylim([0 105]);
xlabel('Areal capacity (mAh/cm^2)'); ylabel('Utilisation to 1.8 V (%)');
title('G2 needs >= 80 % (dashed); this 0-D model gives 100 % everywhere - it cannot test G2');
legend([h0 h1 h2 h3], {'5 mA/cm^2', '10 mA/cm^2', '20 mA/cm^2', '33.3 mA/cm^2'}, 'Location', 'southwest');
set(gca, 'FontSize', 11, 'LineWidth', 0.8);
if ~exist('out', 'dir'), mkdir('out'); end
print(fig, fullfile('out', 'stem_07_scell_utilisation.png'), '-dpng', '-r200');
close(fig);
